head.script:
// 테스트 설명, 유효성 값 설정
//  - 가이드가 영역별 동작(Header/SubTotal/Footer 동작, Body 무시)과 Header inputType 별 동작을 명시하므로,
//    영역 con 옵션 대신 모든 영역의 Column 에 localeRef(websquare_name) / useLocale 을 함께 설정해 한 화면에서 비교한다.
//  - con 은 Column useLocale(미설정/true/false) × GridView useLocale(미설정/true/false) 2개 (조합 9개)
scwin.tData = {
    "description" : "[column > P > useLocale]<br/>Column 에 클라이언트 다국어 기능을 사용할지 설정합니다.",
    "validation" : [
        "다국어 기능을 사용하면 localeRef 속성에 설정한 Key 에 해당하는 텍스트가 Column 의 value 속성값 대신 표시됩니다.",
        "Header/SubTotal/Footer Column 에서만 동작하며 Body Column 에 설정 시 무시됩니다.",
        "미설정 시, GridView 의 useLocale 속성값을 따릅니다.",
        "미설정 시, GridView 의 useLocale='true' 이면 다국어 기능을 사용하고, 그렇지 않으면 사용하지 않습니다.",
        "true 설정 시, GridView 의 useLocale 속성값과 관계없이 다국어 기능을 사용합니다.",
        "false 설정 시, GridView 의 useLocale='true' 여도 다국어 기능을 사용하지 않습니다.",
        "다국어 기능을 사용하려면 config.xml 파일에서 languagePack 항목을 설정하여야 합니다.",
        "다국어 기능은 Key:Value 형식으로 데이터가 정의된 JS 파일에서 Key 값에 해당하는 Value 값을 찾아 특정 속성에 반영합니다.",
        "이때 클라이언트(웹브라우저)에 설정된 언어에 해당하는 JS 파일이 적용됩니다.",
        "Header Column 의 inputType='checkbox' 이면 Column 의 useLocale 속성은 무시되며, GridView 의 useLocale='true' 인 경우에만 다국어 텍스트가 체크박스의 라벨로 표시됩니다.",
        "Header Column 의 inputType='select','checkcombobox','textImage' 이면 다국어 기능이 적용되지 않습니다.",
        "SubTotal/Footer Column 의 inputType='expression' 이면 다국어 기능이 적용되지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean 코드 "1" = 미설정, "2" = true)
    con_useLocale.setValue("2");
    con_gridUseLocale.setValue("1");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 표시 텍스트 확인 대상 (Column ID / 출력 라벨)
scwin.headerInfo = [
    { "id" : "h_cat",   "label" : "분류(text)" },
    { "id" : "h_chk",   "label" : "선택(checkbox) 라벨" },
    { "id" : "h_grade", "label" : "등급(select)" },
    { "id" : "h_skill", "label" : "보유기술(checkcombobox)" },
    { "id" : "h_amt",   "label" : "금액(textImage)" }
];
scwin.subTotalInfo = [
    { "id" : "s_cat", "label" : "소계(text)" },
    { "id" : "s_amt", "label" : "금액(expression)" }
];
scwin.footerInfo = [
    { "id" : "f_cat", "label" : "합계(text)" },
    { "id" : "f_amt", "label" : "금액(expression)" }
];



// comp 생성
//  - localeRef="websquare_name" 과 Column useLocale 은 Header / Body / SubTotal / Footer 의 모든 Column 에 같은 값으로 설정한다 (Column useLocale 미설정은 속성 자체를 넣지 않는다)
//  - Header : 분류 text / 선택 checkbox(checkboxLabel=전체선택) / 등급 select / 보유기술 checkcombobox / 금액 textImage
//  - SubTotal / Footer : 분류 위치 text(소계/합계) / 금액 위치 expression(sum)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] config.xml languagePack 설정(/lang/ko.js, /lang/en.js), 모든 영역의 Column 에 localeRef=websquare_name (ko.js 의 Value 는 웹스퀘어) 고정 설정\n[절차] useLocale (Column) / useLocale (GridView) 변경 -> Target 재생성 -> 표시 텍스트 확인 버튼 클릭\n[확인] 영역별 Column 표시 텍스트가 value(분류, 선택 라벨 전체선택, 소계, 합계 등) 인지 다국어 텍스트인지 확인 (브라우저 언어를 en 으로 바꿔 다시 열면 en.js 의 Value 로 표시)"', '', 'label1');

    // 조건 설정 (gdl_boolean 은 getText() 로 '' / 'true' / 'false' 판단, 미설정은 속성 자체를 넣지 않는다)
    let cUseLocale = con_useLocale.getText();
    let cGridUseLocale = con_gridUseLocale.getText();

    let attrGrid = (cGridUseLocale === '') ? '' : ' useLocale="' + cGridUseLocale + '"';
    let attrCol = ' localeRef="websquare_name"';
    if (cUseLocale !== '') {
        attrCol += ' useLocale="' + cUseLocale + '"';
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (body column id 와 동일한 컬럼 id 사용, SubTotal 그룹 기준 cat 으로 정렬된 데이터)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cat" name="cat" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="skill" name="skill" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amt" name="amt" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "cat" : "가전", "chk" : "0", "grade" : "A", "skill" : "JAVA",       "amt" : "120000" },
        { "cat" : "가전", "chk" : "0", "grade" : "B", "skill" : "SQL",        "amt" : "80000" },
        { "cat" : "가구", "chk" : "0", "grade" : "A", "skill" : "SQL",        "amt" : "350000" },
        { "cat" : "가구", "chk" : "0", "grade" : "B", "skill" : "JAVASCRIPT", "amt" : "45000" }
    ], false);

    // Header select / checkcombobox / Body select / checkcombobox 공통 선택 항목
    let strGrade = '<w2:choices><w2:item><w2:label>A 등급</w2:label><w2:value>A</w2:value></w2:item><w2:item><w2:label>B 등급</w2:label><w2:value>B</w2:value></w2:item></w2:choices>';
    let strSkill = '<w2:choices><w2:item><w2:label>JAVA</w2:label><w2:value>JAVA</w2:value></w2:item><w2:item><w2:label>SQL</w2:label><w2:value>SQL</w2:value></w2:item><w2:item><w2:label>JAVASCRIPT</w2:label><w2:value>JAVASCRIPT</w2:value></w2:item></w2:choices>';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" defaultCellHeight="30"' + attrGrid + ' id="" style="width:760px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="h_cat" value="분류"' + attrCol + '></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="checkbox" id="h_chk" value="선택" checkboxLabel="전체선택"' + attrCol + '></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="select" id="h_grade" value="등급"' + attrCol + '>' + strGrade + '</w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="checkcombobox" id="h_skill" value="보유기술"' + attrCol + '>' + strSkill + '</w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="textImage" imageSrc="/cm/images/base/ico_file.svg" viewType="icon" id="h_amt" value="금액"' + attrCol + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="cat" value=""' + attrCol + '></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="checkbox" id="chk" value=""' + attrCol + '></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="select" id="grade" value=""' + attrCol + '>' + strGrade + '</w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="checkcombobox" id="skill" value=""' + attrCol + '>' + strSkill + '</w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" dataType="number" displayFormat="#,##0" id="amt" value=""' + attrCol + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="cat">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="s_cat" value="소계"' + attrCol + '></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="s_chk" value=""></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="s_grade" value=""></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="s_skill" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="expression" expression="sum(\'amt\')" displayFormat="#,##0" id="s_amt"' + attrCol + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row4">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="f_cat" value="합계"' + attrCol + '></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="f_chk" value=""></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="f_grade" value=""></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="f_skill" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="expression" expression="sum(\'amt\')" displayFormat="#,##0" id="f_amt"' + attrCol + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Header Cell 표시 텍스트 (checkbox 는 체크박스 라벨, 라벨이 없으면 빈값)
scwin.getHeaderText = function (id) {
    let th = target1.render.querySelector("[id='" + target1.id + "_" + id + "']");
    if (!th) {
        return "(없음)";
    }
    if (id === "h_chk") {
        let lbl = th.querySelector("label");
        return lbl ? lbl.textContent : "(라벨 없음)";
    }
    return th.textContent.trim();
}



// SubTotal / Footer Cell 표시 텍스트 (Footer 는 GridView id 접두 id, SubTotal 은 Column id 그대로 렌더되므로 첫번째 소계 Row 기준)
scwin.getAreaText = function (id) {
    let tds = target1.render.querySelectorAll("td[id='" + target1.id + "_" + id + "'], td[id='" + id + "']");
    for (let i = 0; i < tds.length; i++) {
        // 화면에 표시된 Cell 만 대상 (렌더용 숨김 Row 제외)
        if (tds[i].offsetParent !== null) {
            return tds[i].textContent.trim();
        }
    }
    return "(없음)";
}



// 영역별 Column 표시 텍스트 / 적용된 다국어 정보 출력
scwin.btn_checkText_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    // validation 1, 3, 4, 5, 6, 10, 11 판정 출력 (Header)
    bottom.setReturnValue("Header : " + scwin.headerInfo.map(function (o) { return o.label + " = " + scwin.getHeaderText(o.id); }).join(" / "));

    // validation 2 판정 출력 (Body)
    bottom.setReturnValue("Body 분류 Column Row 0 : " + target1.getCellDisplayData(0, "cat") + " / Body 금액 Column Row 0 : " + target1.getCellDisplayData(0, "amt"));

    // validation 1, 3~6, 12 판정 출력 (SubTotal / Footer)
    bottom.setReturnValue("SubTotal : " + scwin.subTotalInfo.map(function (o) { return o.label + " = " + scwin.getAreaText(o.id); }).join(" / "));
    bottom.setReturnValue("Footer : " + scwin.footerInfo.map(function (o) { return o.label + " = " + scwin.getAreaText(o.id); }).join(" / "));

    // validation 7, 8, 9 판정 출력 (config languagePack / 적용된 다국어 JS)
    let objLang = WebSquare.WebSquareLang || {};
    bottom.setReturnValue("config languagePack useLanguagePack = " + WebSquare.core.getConfiguration("/WebSquare/languagePack/@useLanguagePack")
        + " / 브라우저 언어 = " + navigator.language
        + " / 적용된 다국어 JS lang_type = " + objLang["lang_type"] + " / Key websquare_name 의 Value = " + objLang["websquare_name"]);
}
